return $input.all().map(item => {
  const styles = `
<style>
  @page {
    size: A4;
    margin: 16mm;
  }

  body {
    font-family: Arial, sans-serif;
    font-size: 10pt;
    line-height: 1.45;
    color: #253247;
  }

  h1 {
    font-size: 20pt;
    line-height: 1.2;
    color: #17365d;
    margin: 0 0 16px;
  }

  h2, h3 {
    color: #17365d;
    margin: 18px 0 8px;
    break-after: avoid;
  }

  p, ul, ol {
    margin: 8px 0;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
    margin: 12px 0 18px;
  }

  th, td {
    padding: 8px 10px;
    border-bottom: 1px solid #dce3ec;
    vertical-align: top;
  }

  th {
    background: #edf2f8;
    text-align: left;
  }

  thead {
    display: table-header-group;
  }

  tr {
    break-inside: avoid;
  }

  img {
    display: block;
    max-width: 100%;
    max-height: 75mm;
    width: auto;
    height: auto;
    margin: 12px auto;
    break-inside: avoid;
  }

  a {
    color: #175ca4;
    overflow-wrap: anywhere;
  }

  li {
    margin-bottom: 5px;
  }
</style>`;

  let html = item.json.html;
  const input = $('Validate Writer Input').first().json;
  if (input.chart_url) {
    const image = '<img alt="Chart of validated findings" src="' + input.chart_url + '">';
    if (!html.includes('<!-- VALIDATED_CHART -->')) throw new Error('Validated chart placeholder missing');
    html = html.replace('<!-- VALIDATED_CHART -->', image);
  }


  if (typeof html !== 'string' || !html.trim()) {
    throw new Error('Expected report HTML in the html field.');
  }

  const styledHtml = /<\/head>/i.test(html)
    ? html.replace(/<\/head>/i, `${styles}</head>`)
    : `<!DOCTYPE html>
<html>
<head><meta charset="utf-8">${styles}</head>
<body>${html}</body>
</html>`;

  return {
    ...item,
    json: {
      ...item.json,
      html: /^\s*<!doctype html>/i.test(styledHtml) ? styledHtml : '<!DOCTYPE html>\n'+styledHtml
    }
  };
});

function fail(message) { throw new Error('Validation stopped: ' + message); }
function obj(x) { return x !== null && typeof x === 'object' && !Array.isArray(x); }
function parse(x, label = 'JSON') {
  if (typeof x === 'string') {
    let s = x.trim();
    const fence = s.match(/^```(?:json)?\s*\n([\s\S]*?)\n```$/i);
    if (fence) s = fence[1].trim();
    try { x = JSON.parse(s); } catch { fail(label + ' is not complete valid JSON'); }
  }
  if (!obj(x)) fail(label + ' must be an object');
  return x;
}
function arr(x, label) { if (!Array.isArray(x)) fail(label + ' must be an array'); return x; }
function str(x, label) { if (typeof x !== 'string' || !x.trim()) fail(label + ' must be a nonempty string'); return x; }
function strings(x, label) { return arr(x, label).map(v => str(v, label)); }
function norm(s) { return String(s).normalize('NFKC').replace(/\s+/g, ' ').trim(); }
function url(s) { return typeof s === 'string' && /^https?:\/\/[^\s<>"'`]+$/i.test(s); }
function numeric(s) {
  if (typeof s !== 'string' || !/^[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?$/.test(s.trim())) return null;
  const n = Number(s.trim().replace(/,/g, '').replace(/%$/, ''));
  return Number.isFinite(n) ? n : null;
}
function hasNumber(text, token) {
  const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^\\d.,])' + escaped + '(?!\\d|[.,]\\d)').test(text);
}
// Accept only known serialization wrappers; never extract a JSON substring from prose.
function unwrap(x, depth = 0) {
  if (depth > 10) fail('tool result wrapper too deep');
  if (typeof x === 'string') { try { return unwrap(JSON.parse(x), depth + 1); } catch (e) { fail('tool result is not valid JSON'); } }
  if (Array.isArray(x)) { if (x.length !== 1) fail('expected one tool result item'); return unwrap(x[0], depth + 1); }
  if (!obj(x)) fail('invalid tool observation');
  if (obj(x.json)) return unwrap(x.json, depth + 1);
  if (Array.isArray(x.response)) return unwrap(x.response, depth + 1);
  if (Array.isArray(x.content) && x.content.length === 1 && x.content[0].type === 'text') return unwrap(x.content[0].text, depth + 1);
  return x;
}
function trace(item, tool) { return arr(item.intermediateSteps, 'intermediateSteps').filter(s => s.action?.tool === tool); }
function md(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\\`*_{}\[\]|]/g, '\\$&').replace(/\r?\n/g, ' '); }
function mdurl(s) { if (!url(s)) fail('invalid citation URL'); return s.replace(/\(/g, '%28').replace(/\)/g, '%29'); }

const input=$input.first().json;
str(input.analysis_result,'analysis_result');
if (typeof input.chart_url !== 'string') fail('chart_url must be a string');
const a=parse(input.analysis_result,'analysis_result');
if(a.schema_version!==1) fail('unsupported analysis schema');
arr(a.findings,'findings');arr(a.qualitative_evidence,'qualitative_evidence');strings(a.missing_evidence,'missing_evidence');strings(a.tool_errors,'tool_errors');
if(a.chart?.ready===true) {
  if(!/^data:image\/svg\+xml;base64,[A-Za-z0-9+/=]+$/.test(input.chart_url)) fail('validated inline chart is missing');
} else if(input.chart_url!=='') fail('unexpected chart for chart.ready=false');
return [{json:{analysis_result:input.analysis_result,chart_url:input.chart_url,
 writer_context:JSON.stringify({question:a.question,findings:a.findings,qualitative_evidence:a.qualitative_evidence,comparison:a.comparison,missing_evidence:a.missing_evidence,tool_errors:a.tool_errors,research_log:a.research_log})}}];

