function mdurl(s) { if (!url(s)) fail('invalid citation URL'); return s.replace(/\(/g, '%28').replace(/\)/g, '%29'); }

const item=$input.first().json;
const input=$('Validate Writer Input').first().json;
const a=parse(input.analysis_result);
const extra=trace(item,'Researcher');
if(extra.length>1) fail('writer requested research more than once; publication blocked (calls have already occurred)');
let supplemental=null;
if(extra.length===1) {
  try {
    const result=unwrap(extra[0].observation);
    supplemental=parse(result.research_evidence,'supplemental research');
    if(supplemental.schema_version!==1) fail('invalid supplemental schema');
    arr(supplemental.accepted_passages,'supplemental passages');
    strings(supplemental.missing_evidence,'supplemental missing_evidence');
    strings(supplemental.tool_errors,'supplemental tool_errors');
  } catch {
    supplemental={schema_version:1,accepted_passages:[],missing_evidence:['Additional research did not return usable validated evidence.'],tool_errors:['Supplemental research failed or returned an invalid result; it was not retried.']};
  }
}
let text=str(item.output,'writer Markdown').trim();
// Strip only one complete outer fence. Never split on phrases or delete matching lines.
const fenced=text.match(/^```(?:markdown|md)?\s*\n([\s\S]*?)\n```$/i);
if(fenced) text=fenced[1].trim();
if(text.length>80000) fail('writer output too large');
if(!/^#\s+\S/.test(text)) fail('report must begin with a Markdown title');
if(/[<>]/.test(text) || /!\[/.test(text) || /\]\s*\[/.test(text) || /^\s*\[[^\]]+\]:/m.test(text)) fail('raw HTML, images and reference-style links are not allowed in writer prose');
const passages=[...a.qualitative_evidence,...(supplemental?.accepted_passages || []).filter(p=>p.relevance==='direct')];
const allowedUrls=new Set([...a.findings.map(f=>f.source_url),...passages.map(p=>p.url)].map(mdurl));
const links=[...text.matchAll(/\[[^\]\n]+\]\((https?:\/\/[^\s)]+)\)/g)];
for(const m of links) if(!allowedUrls.has(m[1])) fail('writer cited a URL outside validated evidence');
if(/\]\((?!https?:\/\/)/.test(text)) fail('unsupported link scheme');
// Prose may paraphrase, but numeric tokens must occur in validated material.
const support=[...a.findings.map(f=>[f.value,f.year,f.supporting_quote,...f.context_quotes].join(' ')),...passages.map(p=>[p.quote,...p.context_quotes].join(' ')),...a.missing_evidence,...a.tool_errors,a.question].join(' ');
const tokens=s=>s.match(/[+-]?\d+(?:[,.]\d+)*/g)||[];
const allowedNumbers=new Set(tokens(support).map(s=>s.replace(/,/g,'')));
const prose=text.replace(/\]\(https?:\/\/[^\s)]+\)/g,']');
for(const n of tokens(prose)) if(!allowedNumbers.has(n.replace(/,/g,''))) fail('writer introduced unsupported numeric token: '+n);
if((a.findings.length||passages.length) && links.length===0) fail('writer supplied no source citations');
let appendix='\n\n## Verified findings\n\n';
if(a.findings.length) {
  appendix+='| Subject | Value | Unit | Period | Measure | Scope | Source |\n|---|---:|---|---|---|---|---|\n';
  for(const f of a.findings) appendix+='| '+[f.subject,f.value_text,f.unit,f.year,f.measure,f.scope].map(md).join(' | ')+' | [Source]('+mdurl(f.source_url)+') |\n';
} else appendix+='No numeric findings passed validation. Missing values are not estimated.\n';
if(a.chart.ready) appendix+='\n## Chart\n\n<!-- VALIDATED_CHART -->\n\n'+md(a.chart.title)+'. '+md(a.chart.note||'')+'\n';
else appendix+='\nChart omitted: '+md(a.chart.note)+'\n';
if(passages.length) {
  appendix+='\n## Source excerpts and additional research\n\n';
  for(const p of passages) appendix+='> '+md(p.quote)+'\n\n[Source]('+mdurl(p.url)+')'+(p.context_quotes.length?' — Context: '+p.context_quotes.map(md).join(' / '):'')+'\n\n';
  appendix+='Additional research is shown separately and does not change the original findings or chart. Any conflicting evidence remains unresolved.\n';
}
const limitations=[...a.missing_evidence,...a.tool_errors,...a.comparison.caveats,
  ...(a.comparison.comparable?[]:[a.comparison.reason]),...(supplemental?.missing_evidence||[]),...(supplemental?.tool_errors||[])];
appendix+='\n## Evidence limitations\n\n'+([...new Set(limitations)].map(v=>'- '+md(v)).join('\n')||'No additional limitations were recorded by the agents. This does not establish that the sources are complete or error-free.')+'\n\nSource extraction and numeric consistency were checked automatically. Source reliability, table interpretation, coverage, and the meaning of narrative claims require review.\n';
return [{json:{output:text+appendix,analysis_result_input:input.analysis_result,chart_url_input:input.chart_url,
 supplemental_research:supplemental?JSON.stringify(supplemental):'',writer_research_calls:extra.length}}];
